package fraymus.workspace;

import org.json.*;
import java.util.*;

final class SpatialReport {
    static String escape(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
    static JSONArray checks(JSONObject g){return new JSONArray()
        .put(new JSONObject().put("selector","#verdict").put("expectText","Spatial manipulation verified"))
        .put(new JSONObject().put("selector","#goal-id").put("expectText",g.getString("id")))
        .put(new JSONObject().put("selector","#source-hash").put("expectText",g.getJSONObject("spatialBinding").getString("sourceSha256")))
        .put(new JSONObject().put("selector","#model-kind").put("expectText","Native rigid-body forward simulation"))
        .put(new JSONObject().put("selector","#motion .series").put("expectCount",2))
        .put(new JSONObject().put("selector","#release").put("expectText","One actual grab and velocity-preserving release"))
        .put(new JSONObject().put("selector","#scope").put("expectText","Declared-scale scene; no independent real-room calibration or learned universal dynamics claim."))
        .put(new JSONObject().put("selector","#route").put("expectText",g.getJSONObject("metrics").getString("route")));}
    static JSONObject build(JSONObject g,JSONObject run){
        var plan=run.getJSONObject("plan");var m=SpatialStore.verify(run);var scene=run.getJSONObject("definition");StringBuilder lines=new StringBuilder(),csv=new StringBuilder("tick,time_s,actual_x_m,actual_y_m,actual_z_m,predicted_x_m,predicted_y_m,predicted_z_m\n");var a=run.getJSONObject("actual").getJSONArray("samples");var p=plan.getJSONObject("forecast").getJSONArray("samples");
        double minX=Double.POSITIVE_INFINITY,maxX=Double.NEGATIVE_INFINITY;for(var rows:List.of(a,p))for(Object raw:rows){double x=((JSONObject)raw).getJSONArray("position").getDouble(0);minX=Math.min(minX,x);maxX=Math.max(maxX,x);}double span=Math.max(.1,maxX-minX);
        for(int series=0;series<2;series++){var rows=series==0?p:a;StringBuilder points=new StringBuilder();for(Object raw:rows){var row=(JSONObject)raw;var v=row.getJSONArray("position");double x=40+800*row.getInt("tick")/(double)run.getJSONObject("actual").getJSONObject("final").getInt("tick"),y=330-280*(v.getDouble(0)-minX)/span;points.append(String.format(Locale.ROOT,"%.3f,%.3f ",x,y));}lines.append("<polyline class='series' fill='none' stroke='").append(series==0?"#d87c24":"#176c85").append("' stroke-width='").append(series==0?"5":"2").append("' points='").append(points).append("'/>");}
        for(int i=0;i<a.length();i++){var x=a.getJSONObject(i);csv.append(x.getInt("tick")).append(',').append(x.getInt("tick")*BulletRamp.DT);for(var row:List.of(x,p.getJSONObject(i)))for(Object v:row.getJSONArray("position"))csv.append(',').append(v);csv.append('\n');}
        String html="<!doctype html><html lang='en'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Spatial manipulation evidence</title><style>body{font:16px/1.55 system-ui;background:#eff4f1;color:#173b35;margin:0}main{max-width:1000px;margin:auto;padding:26px}section{background:white;padding:20px;border:1px solid #bed0c7;border-radius:12px;margin:20px 0}svg{width:100%;height:auto}code,pre{white-space:pre-wrap;overflow-wrap:anywhere}h1{font-size:32px}.metrics{display:flex;gap:22px;flex-wrap:wrap}.metrics b{display:block;font-size:25px}</style><main><p>FRAYNIX / EDITION 021 / SOURCE-QUALIFIED SPATIAL PROOF</p><h1 id='verdict'>Spatial manipulation verified</h1><p>"+escape(scene.getString("title"))+" · "+escape(scene.getJSONObject("source").getString("kind"))+" (source label)</p><section class='metrics'><div><b>"+String.format(Locale.ROOT,"%.4f",m.getDouble("horizontalErrorM"))+" m</b>Final horizontal error</div><div><b>"+String.format(Locale.ROOT,"%.6f",m.getDouble("forecastRmseM"))+" m</b>Forecast RMSE</div><div><b id='route'>"+escape(m.getString("route"))+"</b>Freshly evaluated route</div></section><section><h2>Predicted versus actual X position</h2><svg id='motion' viewBox='0 0 880 380' role='img' aria-label='Predicted and actual X motion'><path d='M40 20 V345 H850' stroke='#8ba99d' fill='none'/>"+lines+"<text x='50' y='370'>Native time → · orange prediction / blue actual · X metres</text></svg><p id='model-kind'>Native rigid-body forward simulation</p><p>Forecasts ran in isolated worlds using the same declared solver and parameters. Small residuals check execution consistency, not independent physical validity.</p><p id='release'>One actual grab and velocity-preserving release</p></section><section><h2>Source and limits</h2><p id='scope'>Declared-scale scene; no independent real-room calibration or learned universal dynamics claim.</p><p>Scale reference: "+escape(scene.getJSONObject("scaleCheck").toString())+"</p><p>Source note: "+escape(scene.getJSONObject("source").getString("note"))+"</p><p>Source hash <code id='source-hash'>"+scene.getString("sourceSha256")+"</code></p><p>Goal <code id='goal-id'>"+g.getString("id")+"</code></p><p>Object <code>"+escape(plan.getJSONObject("intent").getString("objectId"))+"</code></p><details><summary>Actual metrics and finite candidate routes</summary><pre>"+escape(m.toString(2))+"\n"+escape(plan.getJSONArray("trials").toString(2))+"</pre></details></section></main></html>";
        var files=new JSONObject().put("index.html",html).put("original-scene.json",scene.getString("sourceText")).put("normalized-scene.json",scene.toString(2)).put("native-run.json",run.toString(2)).put("prediction.json",plan.toString(2)).put("motion.csv",csv.toString()).put("verification.json",m.toString(2));
        return new JSONObject().put("title","Spatial proof · "+g.getString("id").substring(0,8)).put("files",files).put("sources",new JSONArray(List.of("goal:"+g.getString("id"),"spatial-scene:"+scene.getString("id"),"sha256:"+scene.getString("sourceSha256"))));
    }
}
